{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE `beastlife-wh-474411.maplemonk.hourly_meta_shopify_final` AS ((with shopy as (WITH fb AS ( SELECT DATE, hour, CAMPAIGN_NAME, CAMPAIGN_ID, AD_NAME, AD_ID, ADSET_NAME, SUM(SPEND) AS SPEND, SUM(IMPRESSIONS) AS IMPRESSIONS, SUM(CLICKS) AS CLICKS FROM `beastlife-wh-474411.maplemonk.beastlife_hourly_MARKETING_CONSOLIDATED` WHERE ACCOUNT_NAME = \"FACEBOOK\" GROUP BY 1, 2, 3, 4, 5,6,7 ), shopify AS ( SELECT Order_Date, FORMAT_TIME(\'%H:00:00\', TIME(ordeR_time)) || \' - \' || FORMAT_TIME(\'%H:59:59\', TIME(ordeR_time)) AS hour_range, utm_campaign, utm_term, SUM( CASE WHEN DATE(Order_Date) >= DATE \'2025-09-22\' THEN (Selling_Price / 1.06) * 0.95 ELSE (Selling_Price / 1.18) * 0.95 END ) AS NSV, SUM(selling_price) * 0.95 AS gross_sales, SUM(selling_price) as sell, COUNT(DISTINCT order_id) AS orders, SUM(quantity) AS quantity, COUNT(DISTINCT CASE WHEN new_customer_flag = \"Repeat\" THEN order_id END) AS repeat_orders, COUNT(DISTINCT CASE WHEN new_customer_flag = \"New\" THEN order_id END) AS new_orders, SUM(CASE WHEN new_customer_flag = \"New\" THEN selling_price * 0.95 ELSE 0 END) AS new_customer_sales, SUM(IF(cod_pp_flag = \"COD\", selling_price * 0.95, 0)) AS cod_sales, SUM(IF(cod_pp_flag = \"Prepaid\", selling_price * 0.95, 0)) AS prepaid_sales, SUM(IF(cod_pp_flag = \"Partial Paid\", selling_price * 0.95, 0)) AS partial_paid_sales, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"COD\" THEN order_id END) AS cod_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"Prepaid\" THEN order_id END) AS prepaid_orders, COUNT(DISTINCT CASE WHEN cod_pp_flag = \"Partial Paid\" THEN order_id END) AS partial_paid_orders FROM `beastlife-wh-474411.maplemonk.Hourly_D2C_master` WHERE channel IN ( \'meta\', \'META\', \'facebook\', \'FACEBOOK\', \'facebook_ads\', \'FACEBOOK_ADS\', \'meta-SiteLink\', \'META-SITELINK\' ) AND order_status = \"SHOPIFY_PROCESSED\" GROUP BY 1, 2, 3,4 ) SELECT COALESCE(fb.`DATE`, shopify.Order_Date) AS DATE, COALESCE(fb.hour, shopify.hour_range) AS hour, fb.CAMPAIGN_NAME, fb.AD_NAME, fb.ADSET_NAME, SUM(fb.SPEND) AS total_spend, SUM(fb.IMPRESSIONS) AS total_impressions, SUM(fb.CLICKS) AS total_clicks, COALESCE(SUM(shopify.gross_sales), 0) AS total_gross_sales, COALESCE(SUM(shopify.sell), 0) AS total_sell, COALESCE(SUM(orders), 0) AS total_orders, COALESCE(SUM(shopify.repeat_orders), 0) AS total_repeat_orders, COALESCE(SUM(shopify.new_orders), 0) AS total_new_orders, COALESCE(SUM(shopify.new_customer_sales), 0) AS total_new_customer_sales, COALESCE(SUM(shopify.cod_sales), 0) AS total_cod_sales, COALESCE(SUM(shopify.prepaid_sales), 0) AS total_prepaid_sales, COALESCE(SUM(shopify.partial_paid_sales), 0) AS total_partial_paid_sales, COALESCE(SUM(shopify.cod_orders), 0) AS total_cod_orders, COALESCE(SUM(shopify.prepaid_orders), 0) AS total_prepaid_orders, COALESCE(SUM(shopify.partial_paid_orders), 0) AS total_partial_paid_orders FROM fb full outer join shopify ON fb.AD_ID = shopify.utm_term AND fb.DATE = shopify.Order_Date and fb.hour = shopify.hour_range GROUP BY 1,2,3,4,5 ORDER BY total_spend DESC), mapped AS ( SELECT TRIM(ad_name) AS meta_ad_name, TRIM(ProductSku_category) meta_sku, type_of_creative, influencer_type, sum(SAFE_CAST(Sku_count AS FLOAT64)) AS Sku_count FROM `beastlife-wh-474411.maplemonk.beastlife_db_MetaadsName` group by 1,2,3,4 ), catalog AS ( SELECT Category, SKU_Code, SKU_Type, Ingredients, Rev_Category, Sub_Category, Category_Type, Product_Name__as_on_Product_Packaging_, sum(cast(MRP as numeric)) as MRP, sum(cast(MRP_Revised as numeric)) as MRP_Revised FROM `beastlife-wh-474411.maplemonk.beastlife_db_MasterCatalogue` group by 1,2,3,4,5,6,7,8 ), calendar AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', event_date) AS event_date, Event, sub_event, FORMAT_DATE(\'%Y%m%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateAsInteger, FORMAT_DATE(\'%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateNumber, EXTRACT(YEAR FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS Year, FORMAT_DATE(\'%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNumber, FORMAT_DATE(\'%Y/%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthNumber, FORMAT_DATE(\'%Y/%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthShort, FORMAT_DATE(\'%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameShort, FORMAT_DATE(\'%B\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameLong, EXTRACT(DAYOFWEEK FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekNumber, FORMAT_DATE(\'%A\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeek, FORMAT_DATE(\'%a\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekShort, CONCAT(\'Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS Quarter, CONCAT( FORMAT_DATE(\'%Y\', PARSE_DATE(\'%Y-%m-%d\', event_date)), \'/Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING) ) AS YearQuarter, CASE WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 1 AND 7 THEN \'W1\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 8 AND 14 THEN \'W2\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 15 AND 21 THEN \'W3\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 22 AND 28 THEN \'W4\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) >= 29 THEN \'W5\' ELSE \'Error\' END AS WeekPeriod FROM `beastlife-wh-474411.maplemonk.beastlife_db_Calender` ), final as (select * from shopy left join mapped on LOWER(shopy.AD_NAME) = LOWER(mapped.meta_ad_name)) select * from final left join catalog on REGEXP_REPLACE(UPPER(TRIM(final.meta_sku)), r\'[^A-Z0-9]\', \'\') = REGEXP_REPLACE(UPPER(TRIM(catalog.SKU_Code)), r\'[^A-Z0-9]\', \'\') left join calendar on final.DATE = calendar.event_date ))",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            